type Config struct {
    Port int `mapstructure:"port"`
}
func loadConfig() Config {
    viper.SetDefault("port", 3000)
    viper.AutomaticEnv()
    var cfg Config
    _ = viper.Unmarshal(&cfg)
    return cfg
}
